using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround;
internal sealed class OriginalGaussianExternalAnalyticCandidateDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Normalized Positive Gaussian Kernel Candidates", H("Normalized Positive Gaussian Kernel Candidates"),
        Blocks(
            Paragraph(Text("The explicit positive-sector formulas and finite rational identities come from the supplied Pro candidate construction, with independent exact algebra verification. Lean proofs differentiate the existing normalized source functions, use their actual squares to cancel the diagonal pole, and reuse the existing half-binomial Picard-Fuchs theorem. The algebra verification is advisory input; the declarations below carry the formal conclusions.")),
            Paragraph(Text("The source functions retain the original Gaussian normalization. These results concern the positive/positive candidate sector. Extracting coefficient recurrences from the analytic PDEs, proving literal candidate equality and continuation, and identifying all four signed sectors remain mathematical obligations. The conditional parity uniqueness theorem is not used as an unconditional identification. These Gaussian results do not complete VOA, CFT, string theory or AdS/CFT.")),
            Describe.Lean(DescribeId.Create("a"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.a"),
