                Blocks(Paragraph(Text("The factor a(u,r)=1-(1-r)u."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("b"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.b"),
                H("b"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The factor b(u)=1-u."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("e"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.E"),
