                Blocks(Paragraph(Text("The reflected-chart denominator E(u,v,r)=1-u-v+(1-r)uv."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("w"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.W"),
                H("W"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("W(u,r)=a(u,r) times the existing positive sourceMode. No square root is chosen independently of the normalized literal source series."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("ell"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.ell"),
                H("ell"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The logarithmic derivative of the existing complex half-binomial period. Its use in the differential equations is restricted to the open unit disk, where period_ne_zero applies."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("correction"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.correction"),
                H("correction"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The common period correction r(1-r)ell(r). Its derivative is obtained from the existing picard_fuchs theorem and actual period nonvanishing."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rationalt"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.rationalT"),
                H("rationalT"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The regular rational T factor r(1+(1-r)uv)/(2E)+r squared uv/E squared."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("rationalj"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.rationalJ"),
                H("rationalJ"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The off-diagonal rational J factor [u b(v) a(u,r)+v b(u) a(v,r)]/[2(u-v) squared]."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("cauchy"),
