                H("cauchy"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The Cauchy subtraction (u+v)/[2(u-v) squared], used only off the diagonal when identifying the regular J expression."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("candidatet"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.candidateT"),
                H("candidateT"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The product of the two actual positive sourceMode functions times rationalT minus correction. The full T identity contribution is retained in the proposed formula; equality with the original full externalT is not assumed."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("candidatej"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.candidateJ"),
                H("candidateJ"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The regular expression M(u)M(v)[r/4-correction+r squared (u+v)/(4 b(u)b(v)(W(u)+W(v)) squared)]. It has no inverse external coordinate and no explicit diagonal denominator."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("l"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalAnalyticCandidate.L"),
